(function(){
 'use strict';
 async function cep(input,target){const value=input.value.replace(/\D/g,'');if(value.length!==8)return;const r=await fetch('/api/delivery/cep?cep='+value,{credentials:'same-origin'}),d=await r.json();if(!r.ok)throw Error(d.message||'CEP não encontrado.');target.value=d.address+', ';target.focus()}
 function enhanceLogistics(){const form=document.getElementById('logistics-settings');if(!form||form.dataset.stabilized)return;form.dataset.stabilized='1';const block=document.createElement('div');block.className='logistics-block';block.innerHTML='<h3>Pendências e reoferta</h3><label>Intervalo de reoferta (segundos)<input name="reoffer_delay_seconds" type="number" min="5" max="600" value="30"></label><label>Entrar em pendência após (segundos)<input name="pending_after_seconds" type="number" min="15" max="3600" value="90"></label><label>Máximo de rodadas<input name="max_offer_rounds" type="number" min="1" max="50" value="5"></label><label>Fuso da operação<select name="operation_timezone"><option value="America/Sao_Paulo">America/Sao_Paulo</option><option value="UTC">UTC</option></select></label><label>Som das ofertas<select name="offer_sound_enabled"><option value="true">Ativo</option><option value="false">Desativado</option></select></label><label>Notificações push<select name="push_enabled"><option value="true">Ativas</option><option value="false">Desativadas</option></select></label>';form.querySelector('.logistics-actions')?.before(block)}
 function enhance(){const form=document.getElementById('new-merchant');if(form&&!form.dataset.enhanced){form.dataset.enhanced='1';const email=form.elements.email,password=document.createElement('label');password.textContent='Senha inicial';password.innerHTML+=' <input name="password" type="password" minlength="8" autocomplete="new-password" required>';email.closest('label').after(password);const address=form.elements.address,cepLabel=document.createElement('label');cepLabel.textContent='CEP';cepLabel.innerHTML+=' <input name="cep_lookup" inputmode="numeric" maxlength="9" placeholder="00000-000">';address.closest('label').before(cepLabel);cepLabel.querySelector('input').addEventListener('input',e=>{if(e.target.value.replace(/\D/g,'').length===8)cep(e.target,address).catch(x=>window.dispatchEvent(new CustomEvent('vuppi:admin-error',{detail:x.message})))});form.querySelector('.muted').textContent='Crie a conta e o cadastro do estabelecimento em uma única etapa.'}enhanceLogistics()}
 new MutationObserver(enhance).observe(document.documentElement,{childList:true,subtree:true});addEventListener('DOMContentLoaded',enhance);
})();
